  const note = document.getElementById("ann-note").value.trim();
  const tags = document.getElementById("ann-tags").value.split(",").map((t) => t.trim()).filter(Boolean);
  const editId = p.dataset.edit;
  if (!note && !tags.length) {
    document.getElementById("ann-err").textContent = "a note or a tag is needed";
